<?php
declare(strict_types=1);
requireRole('subject-officer');
require_once __DIR__.'/../../config/database.php';
require_once __DIR__.'/../../includes/activity.php';
require_once __DIR__.'/../../includes/prohibited-item-selector.php';
$activePage='item-categories';$errors=[];$success=(string)($_SESSION['flash_success']??'');unset($_SESSION['flash_success']);$db=database();

function itemConfigRedirect(string $message):never{$_SESSION['flash_success']=$message;unset($_SESSION['csrf_token']);header('Location: dashboard.php?page=item-categories');exit;}
function configuredBeneficiaryFields(string $raw):array{
 $raw=trim($raw);if($raw==='')return [];$fields=json_decode($raw,true,16,JSON_THROW_ON_ERROR);if(!is_array($fields)||!array_is_list($fields)||count($fields)>10)throw new RuntimeException('Add up to 10 beneficiary information fields.');$clean=[];$names=[];
 foreach($fields as $field){$label=preg_replace('/\s+/',' ',trim((string)($field['label']??'')));$type=(string)($field['type']??'');if(mb_strlen($label)<2||mb_strlen($label)>100||!in_array($type,['text','number','date','image','pdf'],true))throw new RuntimeException('Each beneficiary information field needs a valid name and type.');$key=mb_strtolower($label);if(isset($names[$key]))throw new RuntimeException('Beneficiary information field names must be different.');$names[$key]=true;$clean[]=['label'=>$label,'type'=>$type];}
 return $clean;
}

// The enhanced item form posts here so the field definition and eligibility rule are saved together.
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='save-item-with-detail'){
 try{
  if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))throw new RuntimeException('Your session expired. Refresh the page and try again.');
  $disability=filter_input(INPUT_POST,'disability_type_id',FILTER_VALIDATE_INT);$name=preg_replace('/\s+/',' ',trim((string)($_POST['item_name']??'')));$variety=preg_replace('/\s+/',' ',trim((string)($_POST['variety']??'')));$period=filter_input(INPUT_POST,'restriction_value',FILTER_VALIDATE_INT);$unit=(string)($_POST['restriction_unit']??'');$blocked=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['prohibited_item_ids']??[])))));$detailFields=configuredBeneficiaryFields((string)($_POST['beneficiary_fields_json']??''));$firstField=$detailFields[0]??['label'=>null,'type'=>'text'];$detailLabel=$firstField['label'];$detailType=in_array($firstField['type'],['text','number'],true)?$firstField['type']:'text';
  if(!$disability||mb_strlen($name)<2||mb_strlen($name)>100)throw new RuntimeException('Select a disability type and enter a valid item name.');if($period===false||$period<0||$period>100||!in_array($unit,['months','years'],true))throw new RuntimeException('Enter a valid probation period and unit.');$months=$unit==='years'?$period*12:$period;
  $db->beginTransaction();$q=$db->prepare("SELECT id FROM disability_types WHERE id=:id AND status='active'");$q->execute(['id'=>$disability]);if(!$q->fetchColumn())throw new RuntimeException('The selected disability type is unavailable.');$q=$db->prepare("INSERT INTO item_categories(name,distribution_type,returnable,status,created_by) VALUES('Configured Disability Aid','request-based',0,'active',:user) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status='active'");$q->execute(['user'=>$_SESSION['user_id']]);$category=(int)$db->lastInsertId();$q=$db->prepare('SELECT id FROM inventory_items WHERE item_name=:name AND variety=:variety LIMIT 1');$q->execute(['name'=>$name,'variety'=>$variety]);$item=(int)$q->fetchColumn();if(!$item){$q=$db->prepare("INSERT INTO inventory_items(item_name,category,variety,quantity,category_id) VALUES(:name,'Configured Disability Aid',:variety,0,:category)");$q->execute(['name'=>$name,'variety'=>$variety,'category'=>$category]);$item=(int)$db->lastInsertId();}$q=$db->prepare('SELECT COUNT(*) FROM disability_aid_items WHERE item_id=:item AND is_system=1');$q->execute(['item'=>$item]);if((int)$q->fetchColumn())throw new RuntimeException('This is a built-in aid item. Open its configured rule to add beneficiary information.');
  $q=$db->prepare("INSERT INTO disability_aid_items(disability_type_id,item_id,restriction_months,beneficiary_field_label,beneficiary_field_type,status,created_by) VALUES(:disability,:item,:months,:label,:type,'active',:user) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),restriction_months=VALUES(restriction_months),beneficiary_field_label=VALUES(beneficiary_field_label),beneficiary_field_type=VALUES(beneficiary_field_type),status='active'");$q->execute(['disability'=>$disability,'item'=>$item,'months'=>$months,'label'=>$detailLabel,'type'=>$detailType,'user'=>$_SESSION['user_id']]);$rule=(int)$db->lastInsertId();$db->prepare('DELETE FROM disability_aid_item_fields WHERE disability_aid_item_id=:rule')->execute(['rule'=>$rule]);$addField=$db->prepare('INSERT INTO disability_aid_item_fields(disability_aid_item_id,field_label,field_type,display_order) VALUES(:rule,:label,:type,:position)');foreach($detailFields as $position=>$detailField)$addField->execute(['rule'=>$rule,'label'=>$detailField['label'],'type'=>$detailField['type'],'position'=>$position+1]);$db->prepare('DELETE FROM disability_item_prohibitions WHERE disability_aid_item_id=:rule')->execute(['rule'=>$rule]);$add=$db->prepare('INSERT INTO disability_item_prohibitions(disability_aid_item_id,prohibited_item_id) VALUES(:rule,:item)');foreach($blocked as $blockedItem)if($blockedItem!==$item)$add->execute(['rule'=>$rule,'item'=>$blockedItem]);$db->commit();logActivity('Disability Aid Configuration','Configured item eligibility and beneficiary fields','ITEM-'.$item);itemConfigRedirect('Aid item configuration saved.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to save the aid configuration.';}
}

if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')!=='save-item-with-detail'){
 if(!verifyCsrfToken((string)($_POST['csrf_token']??'')))$errors[]='Your session expired. Refresh the page and try again.';
 else try{
  $action=(string)($_POST['action']??'');
  if($action==='add-disability'){
   $name=preg_replace('/\s+/',' ',trim((string)($_POST['disability_name']??'')));
   if(mb_strlen($name)<2||mb_strlen($name)>150)throw new RuntimeException('Enter a disability type between 2 and 150 characters.');
   $q=$db->prepare("INSERT INTO disability_types(name,status,created_by) VALUES(:name,'active',:user) ON DUPLICATE KEY UPDATE status='active'");$q->execute(['name'=>$name,'user'=>$_SESSION['user_id']]);
   logActivity('Disability Aid Configuration','Added disability type',$name);itemConfigRedirect('Disability type saved.');
  }
  if($action==='delete-disability'){
   $disability=filter_input(INPUT_POST,'disability_type_id',FILTER_VALIDATE_INT);if(!$disability)throw new RuntimeException('Select a valid disability type.');
   $db->beginTransaction();$q=$db->prepare('SELECT name,is_system FROM disability_types WHERE id=:id FOR UPDATE');$q->execute(['id'=>$disability]);$disabilityRow=$q->fetch();if(!$disabilityRow)throw new RuntimeException('The selected disability type no longer exists.');$name=(string)$disabilityRow['name'];if((int)$disabilityRow['is_system']===1)throw new RuntimeException('Built-in disability types cannot be removed.');
   // Keep configured rules intact by allowing deletion only for a disability that is not in use.
   $q=$db->prepare('SELECT COUNT(*) FROM disability_aid_items WHERE disability_type_id=:id');$q->execute(['id'=>$disability]);if((int)$q->fetchColumn())throw new RuntimeException('This disability type is used by an eligibility rule. Edit or delete that rule first.');
   $db->prepare('DELETE FROM disability_types WHERE id=:id')->execute(['id'=>$disability]);$db->commit();logActivity('Disability Aid Configuration','Deleted disability type',$name,'deleted');itemConfigRedirect('Disability type removed permanently.');
  }
  if($action==='save-item'){
   $disability=filter_input(INPUT_POST,'disability_type_id',FILTER_VALIDATE_INT);$name=preg_replace('/\s+/',' ',trim((string)($_POST['item_name']??'')));$variety=preg_replace('/\s+/',' ',trim((string)($_POST['variety']??'')));$period=filter_input(INPUT_POST,'restriction_value',FILTER_VALIDATE_INT);$unit=(string)($_POST['restriction_unit']??'');$blocked=array_values(array_unique(array_filter(array_map('intval',(array)($_POST['prohibited_item_ids']??[])))));
   if(!$disability)throw new RuntimeException('Select a disability type.');if(mb_strlen($name)<2||mb_strlen($name)>100)throw new RuntimeException('Enter a valid item name.');if($period===false||$period<0||$period>100)throw new RuntimeException('Enter a valid probation period between 0 and 100.');if(!in_array($unit,['months','years'],true))throw new RuntimeException('Select months or years.');$months=$unit==='years'?$period*12:$period;
   $db->beginTransaction();$q=$db->prepare("SELECT id FROM disability_types WHERE id=:id AND status='active'");$q->execute(['id'=>$disability]);if(!$q->fetchColumn())throw new RuntimeException('The selected disability type is unavailable.');
   // A shared technical category keeps all existing stock workflows compatible.
   $q=$db->prepare("INSERT INTO item_categories(name,distribution_type,returnable,status,created_by) VALUES('Configured Disability Aid','request-based',0,'active',:user) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status='active'");$q->execute(['user'=>$_SESSION['user_id']]);$category=(int)$db->lastInsertId();
   $q=$db->prepare('SELECT id FROM inventory_items WHERE item_name=:name AND variety=:variety LIMIT 1');$q->execute(['name'=>$name,'variety'=>$variety]);$item=(int)$q->fetchColumn();if(!$item){$q=$db->prepare("INSERT INTO inventory_items(item_name,category,variety,quantity,category_id) VALUES(:name,'Configured Disability Aid',:variety,0,:category)");$q->execute(['name'=>$name,'variety'=>$variety,'category'=>$category]);$item=(int)$db->lastInsertId();}$q=$db->prepare('SELECT COUNT(*) FROM disability_aid_items WHERE item_id=:item AND is_system=1');$q->execute(['item'=>$item]);if((int)$q->fetchColumn())throw new RuntimeException('This is a built-in aid item. Open its configured rule to add beneficiary information.');
   $q=$db->prepare("INSERT INTO disability_aid_items(disability_type_id,item_id,restriction_months,status,created_by) VALUES(:disability,:item,:months,'active',:user) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),restriction_months=VALUES(restriction_months),status='active'");$q->execute(['disability'=>$disability,'item'=>$item,'months'=>$months,'user'=>$_SESSION['user_id']]);$rule=(int)$db->lastInsertId();
   $db->prepare('DELETE FROM disability_item_prohibitions WHERE disability_aid_item_id=:rule')->execute(['rule'=>$rule]);$add=$db->prepare('INSERT INTO disability_item_prohibitions(disability_aid_item_id,prohibited_item_id) VALUES(:rule,:item)');foreach($blocked as $blockedItem)if($blockedItem!==$item)$add->execute(['rule'=>$rule,'item'=>$blockedItem]);
   $db->commit();logActivity('Disability Aid Configuration','Configured item eligibility','ITEM-'.$item);itemConfigRedirect('Aid item and probation rule saved.');
  }
  throw new RuntimeException('Invalid configuration action.');
 }catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log($e->getMessage());$errors[]=$e instanceof RuntimeException?$e->getMessage():'Unable to save the aid configuration.';}
}
try{$disabilities=$db->query("SELECT id,name,is_system FROM disability_types WHERE status='active' ORDER BY is_system DESC,name")->fetchAll();$aidItems=$db->query('SELECT id,item_name,variety FROM inventory_items ORDER BY item_name,variety')->fetchAll();}catch(PDOException $e){error_log($e->getMessage());$disabilities=$aidItems=[];$errors[]='Aid configuration is unavailable. Run the latest database migration.';}
?>
